# 🟡 中风险：会向 ACR 写入新仓库（不影响源端与线上服务）
# image-syncer 配置示例（auth.json）
{
  "auth": [
    {
      "username": "harbor-user",
      "password": "<自建Harbor账号>",
      "registry": "harbor.corp.example.com"
    },
    {
      "username": "acr-user",
      "password": "<ACR固定密码>",
      "registry": "registry.cn-hangzhou.aliyuncs.com"
    }
  ],
  "images": {
    "harbor.corp.example.com/prod/": {
      "dest": [
        "registry.cn-hangzhou.aliyuncs.com/prod/"
      ]
    }
  }
}
